ALTER TABLE users ADD COLUMN access_profile TEXT NOT NULL DEFAULT '' CHECK(access_profile IN ('','OPERATOR'));
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_tenant_id ON users(tenant_id,id);
CREATE TABLE user_barns (tenant_id TEXT NOT NULL, user_id TEXT NOT NULL, barn_id TEXT NOT NULL, preferred INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,barn_id), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE population_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, barn_id TEXT NOT NULL, day TEXT NOT NULL, birds INTEGER NOT NULL CHECK(birds>0), source TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,barn_id,day), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE integration_sources (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, resource TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('manual','api','https')), format TEXT NOT NULL CHECK(format IN ('csv','xlsx')), mapping TEXT NOT NULL, endpoint TEXT NOT NULL DEFAULT '', secret TEXT, token_hash TEXT UNIQUE, interval_minutes INTEGER NOT NULL CHECK(interval_minutes>=15), active INTEGER NOT NULL DEFAULT 1, next_run_at TEXT NOT NULL, last_run_at TEXT, last_status TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE import_runs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, source_id TEXT NOT NULL, fingerprint TEXT NOT NULL, status TEXT NOT NULL, accepted INTEGER NOT NULL DEFAULT 0, duplicates INTEGER NOT NULL DEFAULT 0, error TEXT, payload TEXT, started_at TEXT NOT NULL, finished_at TEXT, FOREIGN KEY(tenant_id,source_id) REFERENCES integration_sources(tenant_id,id));
CREATE INDEX idx_import_history ON import_runs(tenant_id,source_id,started_at);
CREATE TABLE imported_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, source_id TEXT NOT NULL, fingerprint TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(source_id,fingerprint), FOREIGN KEY(tenant_id,source_id) REFERENCES integration_sources(tenant_id,id));
CREATE TABLE job_leases (id TEXT PRIMARY KEY, owner TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE report_schedules (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, frequency TEXT NOT NULL CHECK(frequency IN ('daily','weekly')), weekday INTEGER NOT NULL CHECK(weekday>=0 AND weekday<=6), send_time TEXT NOT NULL, timezone TEXT NOT NULL, barn_ids TEXT NOT NULL, indicators TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, last_slot TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE report_recipients (tenant_id TEXT NOT NULL, schedule_id TEXT NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY(schedule_id,user_id), FOREIGN KEY(tenant_id,schedule_id) REFERENCES report_schedules(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE TABLE report_deliveries (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, schedule_id TEXT NOT NULL, user_id TEXT NOT NULL, slot TEXT NOT NULL, status TEXT NOT NULL, subject TEXT NOT NULL, html TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL, sent_at TEXT, UNIQUE(schedule_id,user_id,slot), FOREIGN KEY(tenant_id,schedule_id) REFERENCES report_schedules(tenant_id,id), FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id));
CREATE INDEX idx_report_queue ON report_deliveries(status,next_attempt_at);
CREATE INDEX idx_sources_due ON integration_sources(active,next_run_at);
